mapper.insert:
INSERT /*LGVATT00014.insertBonusKpiForOs*/ INTO TB_PAY_KPI_BONUS_OS
( pay_roll_kpi_bonus_id
  ,no
  ,time_and_attendance_yyyymm
  ,status
  ,vendor_code
  ,recuitiment_taget
  ,recuitiment_actual
  ,kpi_rate
  ,kpi_bonus
 ,creation_user_id 					/* 사용자ID */
 ,creation_date 					/* 등록일자 */
 ,last_update_user_id 				/* 최종수정자ID */
 ,last_update_date 					/* 수정일자 */
) values
( SQ_TB_PAY_BONUS_KPI_OS.NEXTVAL
 ,#{no}
 ,#{timeAndAttendanceYyyymm}
 ,#{status}
 ,#{vendorCode}
 ,#{recuitimentTaget}
 ,#{recuitimentActual}
 ,#{kpiRate}
 ,#{kpiBonus}
 ,#{applicationUserId}
 ,trunc(sysdate)
 ,#{applicationUserId}
 ,trunc(sysdate)
)

mapper.update:
 UPDATE /*LGVATT00014.updateBonusKpiForOs*/
        TB_PAY_KPI_BONUS_OS 
SET    time_and_attendance_yyyymm    #{timeAndAttendanceYyyymm}
      ,status    #{status}
      ,vendor_code    #{vendorCode}
      ,recuitiment_taget    #{recuitimentTaget}
      ,recuitiment_actual    #{recuitimentActual}
      ,kpi_rate    #{kpiRate}
      ,kpi_bonus    #{kpiBonus}
      ,last_update_user_id              = #{applicationUserId}            							/* 최종수정사용자아이디 */
      ,last_update_date                 = trunc(sysdate)                 							/* 최종수정일자 */
 WHERE  pay_roll_kpi_bonus_id               = #{payRollKpiBonusId}
